}

AddStatLine(iMenu, const szName[], iValue)
{
	new szLine[MAX_MENU_LINE];
	formatex(szLine, charsmax(szLine), "%s: \r%d", szName, iValue);
	menu_additem(iMenu, szLine, "0");
}

public StatsMenu_Handler(id, menu, item)
{
	if (item == MENU_EXIT)
	{
		menu_destroy(menu);
